1	package posemap
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"sort"
8		"sync"
9	)
10	
11	// Map 是一份带持久化文件的二维轨迹与路标地图。零值不可用，须经 Create
12	// 或 Open 得到。单个 Map 可被多个 goroutine 并发使用。
13	type Map struct {
14		mu     sync.Mutex
15		path   string
16		state  *mapState
17		closed bool
18	}
19	
20	// mapState 是地图的全部内存状态。
21	type mapState struct {
22		config     Config
23		trajectory []Pose // 按时间严格递增；trajectory[0] 为初始位姿
24		landmarks  map[string]*landmarkState
25		segments   map[string]*segmentRecord
26	}
27	
28	// landmarkState 是路标在地图坐标下的聚合状态。
29	type landmarkState struct {
30		x     float64
31		y     float64
32		count int
33	}
34	
35	// segmentRecord 记录一个已成功保存的段：内容指纹与首次导入结果，
36	// 供相同内容重复导入时直接返回。
37	type segmentRecord struct {
38		hash   string
39		result ImportResult
40	}
41	
42	// ImportResult 是一次成功段导入的结果：本段末位姿及方差，以及本段
43	// 涉及（观测到）的全部路标标识（去重、按标识排序）。
44	type ImportResult struct {
45		EndPose     Pose
46		LandmarkIDs []string
47	}
48	
49	// Create 在 path 处创建一份新地图并写入初始文件。path 已存在时返回
50	// 错误，以免覆盖既有数据（既有地图请用 Open）。
51	func Create(path string, cfg Config) (*Map, error) {
52		if err := validateConfig(cfg); err != nil {
53			return nil, err
54		}
55		st := &mapState{
56			config:     cfg,
57			trajectory: []Pose{{Time: cfg.InitialTime, X: cfg.InitialX, Y: cfg.InitialY, Heading: cfg.InitialHeading, Variance: cfg.InitialVariance}},
58			landmarks:  make(map[string]*landmarkState),
59			segments:   make(map[string]*segmentRecord),
60		}
61		m := &Map{path: path, state: st}
62		// O_EXCL：目标已存在即失败，绝不当作新地图覆盖。
63		if err := m.saveExclusive(); err != nil {
64			return nil, err
65		}
66		return m, nil
67	}
68	
69	// Open 打开 path 处由 Create/导入生成的地图文件。文件不存在时返回
70	// 包装了 fs.ErrNotExist 的错误；文件损坏返回可 errors.Is(ErrCorrupt)
71	// 的错误；格式版本不支持返回 ErrUnsupportedVersion。Open 绝不覆盖
72	// 无法识别的文件。
73	func Open(path string) (*Map, error) {
74		st, err := loadFile(path)
75		if err != nil {
76			return nil, err
77		}
78		return &Map{path: path, state: st}, nil
79	}
80	
81	// Path 返回地图对应的本地数据文件路径。
82	func (m *Map) Path() string {
83		m.mu.Lock()
84		defer m.mu.Unlock()
85		return m.path
86	}
87	
88	// Close 关闭地图。每次成功导入都已落盘，Close 本身不修改数据文件；
89	// 关闭后再调用其他方法返回 ErrClosed。
90	func (m *Map) Close() error {
91		m.mu.Lock()
92		defer m.mu.Unlock()
93		m.closed = true
94		return nil
95	}
96	
97	func validateConfig(cfg Config) error {
98		switch {
99		case !isFinite(cfg.InitialX) || !isFinite(cfg.InitialY) || !isFinite(cfg.InitialHeading):
100			return fmt.Errorf("%w: non-finite initial pose", ErrInvalidConfig)
101		case !isFinite(cfg.InitialVariance) || cfg.InitialVariance < 0:
102			return fmt.Errorf("%w: initial variance must be non-negative and finite", ErrInvalidConfig)
103		case cfg.MaxInterval <= 0:
104			return fmt.Errorf("%w: max interval must be positive", ErrInvalidConfig)
105		case !isFinite(cfg.MergeDistance) || cfg.MergeDistance <= 0:
106			return fmt.Errorf("%w: merge distance must be positive and finite", ErrInvalidConfig)
107		default:
108			return nil
109		}
110	}
111	
112	// ImportSegment 导入一批带非空段标识的有序帧。
113	//
114	// 整段要么全部生效（含落盘），要么因可区分的 *RejectError 被整段拒绝，
115	// 此前已提交的位姿、路标、观测次数不受影响。已成功保存的段标识再次以
116	// 相同内容导入时，直接返回首次导入的结果且不改变当前数据；同一标识
117	// 对应不同内容则以 RejectDuplicateMismatch 拒绝。
118	func (m *Map) ImportSegment(seg Segment) (ImportResult, error) {
119		m.mu.Lock()
120		defer m.mu.Unlock()
121		if m.closed {
122			return ImportResult{}, ErrClosed
123		}
124		st := m.state
125	
126		if seg.ID == "" {
127			return ImportResult{}, &RejectError{Kind: RejectEmptyID}
128		}
129		if len(seg.Frames) == 0 {
130			return ImportResult{}, &RejectError{Kind: RejectEmptySegment}
131		}
132	
133		// 已保存段：相同内容直接返回首次结果；不同内容明确拒绝。
134		// 不做任何校验或状态变更，即使其后又导入过其他段。
135		if rec, ok := st.segments[seg.ID]; ok {
136			if canonicalHash(seg.Frames) == rec.hash {
137				return cloneResult(rec.result), nil
138			}
139			return ImportResult{}, &RejectError{Kind: RejectDuplicateMismatch, Landmark: seg.ID, HasLandmark: true}
140		}
141	
142		// ---- 在暂存区上校验并推演，真实状态此时保持不变 ----
143		cur := st.trajectory[len(st.trajectory)-1]
144		prevTime := cur.Time
145		newPoses := make([]Pose, 0, len(seg.Frames))
146		staged := make(map[string]*landmarkState) // 本段触及路标的暂存聚合
147		touched := make(map[string]struct{})
148	
149		reject := func(kind string, frame int) (ImportResult, error) {
150			return ImportResult{}, &RejectError{Kind: kind, Frame: frame, HasFrame: true}
151		}
152	
153		for i, f := range seg.Frames {
154			// 时间：严格递增；首帧必须晚于初始时间或上一段末帧。
155			if f.Time <= prevTime {
156				return reject(RejectTimeOrder, i)
157			}
158			// 相邻位姿间隔上限。
159			if f.Time-prevTime > m.state.config.MaxInterval {
160				return reject(RejectInterval, i)
161			}
162			// 运动数值有限、方差非负。
163			if !isFinite(f.DX) || !isFinite(f.DY) || !isFinite(f.DHeading) || !isFinite(f.MoveVariance) {
164				return reject(RejectNonFinite, i)
165			}
166			if f.MoveVariance < 0 {
167				return reject(RejectNegativeVariance, i)
168			}
169			// 观测标识非空、观测位置有限。
170			for _, ob := range f.Observations {
171				if ob.ID == "" {
172					return reject(RejectEmptyID, i)
173				}
174				if !isFinite(ob.X) || !isFinite(ob.Y) {
175					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
176				}
177			}
178	
179			// 运动：先按运动前朝向把平移转换到地图坐标，再更新朝向并归一。
180			nx, ny := localToMap(cur.X, cur.Y, cur.Heading, f.DX, f.DY)
181			cur = Pose{
182				Time:     f.Time,
183				X:        nx,
184				Y:        ny,
185				Heading:  normalizeAngle(cur.Heading + f.DHeading),
186				Variance: cur.Variance + f.MoveVariance,
187			}
188			newPoses = append(newPoses, cur)
189	
190			// 观测按运动完成后的位姿转换到地图坐标，同帧按输入次序处理。
191			for _, ob := range f.Observations {
192				mx, my := localToMap(cur.X, cur.Y, cur.Heading, ob.X, ob.Y)
193				lm := staged[ob.ID]
194				if lm == nil {
195					lm = st.landmarks[ob.ID]
196					if lm != nil {
197						// 复制已提交路标，避免提前修改真实状态。
198						cp := *lm
199						lm = &cp
200					}
201				}
202				if lm != nil {
203					if math.Hypot(mx-lm.x, my-lm.y) > m.state.config.MergeDistance {
204						return ImportResult{}, &RejectError{Kind: RejectLandmarkConflict, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
205					}
206					lm.x = (lm.x*float64(lm.count) + mx) / float64(lm.count+1)
207					lm.y = (lm.y*float64(lm.count) + my) / float64(lm.count+1)
208					lm.count++
209				} else {
210					lm = &landmarkState{x: mx, y: my, count: 1}
211				}
212				staged[ob.ID] = lm
213				touched[ob.ID] = struct{}{}
214			}
215	
216			prevTime = f.Time
217		}
218	
219		ids := make([]string, 0, len(touched))
220		for id := range touched {
221			ids = append(ids, id)
222		}
223		sort.Strings(ids)
224		res := ImportResult{EndPose: cur, LandmarkIDs: ids}
225	
226		// ---- 全部校验通过：提交内存状态并落盘；落盘失败精确回滚 ----
227		trajLenBefore := len(st.trajectory)
228		type undoLandmark struct {
229			lm *landmarkState
230			ok bool
231		}
232		undo := make(map[string]undoLandmark, len(staged))
233		for id, nl := range staged {
234			old, ok := st.landmarks[id]
235			undo[id] = undoLandmark{old, ok}
236			st.landmarks[id] = nl
237		}
238		st.trajectory = append(st.trajectory, newPoses...)
239		st.segments[seg.ID] = &segmentRecord{hash: canonicalHash(seg.Frames), result: cloneResult(res)}
240	
241		if err := m.saveReplace(); err != nil {
242			st.trajectory = st.trajectory[:trajLenBefore]
243			for id, u := range undo {
244				if u.ok {
245					st.landmarks[id] = u.lm
246				} else {
247					delete(st.landmarks, id)
248				}
249			}
250			delete(st.segments, seg.ID)
251			return ImportResult{}, err
252		}
253		return res, nil
254	}
255	
256	func cloneResult(r ImportResult) ImportResult {
257		ids := make([]string, len(r.LandmarkIDs))
258		copy(ids, r.LandmarkIDs)
259		r.LandmarkIDs = ids
260		return r
261	}
262	
263	// CurrentPose 返回当前位姿及其位置方差；尚无帧导入时返回初始位姿。
264	func (m *Map) CurrentPose() (Pose, error) {
265		m.mu.Lock()
266		defer m.mu.Unlock()
267		if m.closed {
268			return Pose{}, ErrClosed
269		}
270		return m.state.trajectory[len(m.state.trajectory)-1], nil
271	}
272	
273	// PoseAt 返回不晚于 t 的最后一份历史位姿及其方差。t 早于初始时间时
274	// 返回 ErrNotFound。
275	func (m *Map) PoseAt(t int64) (Pose, error) {
276		m.mu.Lock()
277		defer m.mu.Unlock()
278		if m.closed {
279			return Pose{}, ErrClosed
280		}
281		tr := m.state.trajectory
282		// j 为第一个时间 > t 的位置。
283		j := sort.Search(len(tr), func(j int) bool { return tr[j].Time > t })
284		if j == 0 {
285			return Pose{}, ErrNotFound
286		}
287		return tr[j-1], nil
288	}
289	
290	// Rect 描述一个包含边界的轴对齐矩形查询区域，单位米。
291	type Rect struct {
292		MinX, MinY, MaxX, MaxY float64
293	}
294	
295	// LandmarksInRect 返回矩形（含边界）内的路标及观测次数，按标识排序；
296	// 区域为空时返回非 nil 的空切片。上下界颠倒或含非有限值时报 ErrInvalidRect。
297	func (m *Map) LandmarksInRect(r Rect) ([]Landmark, error) {
298		m.mu.Lock()
299		defer m.mu.Unlock()
300		if m.closed {
301			return nil, ErrClosed
302		}
303		if !isFinite(r.MinX) || !isFinite(r.MinY) || !isFinite(r.MaxX) || !isFinite(r.MaxY) ||
304			r.MinX > r.MaxX || r.MinY > r.MaxY {
305			return nil, fmt.Errorf("%w: min bounds must not exceed max bounds and all values must be finite", ErrInvalidRect)
306		}
307		var out []Landmark
308		for id, lm := range m.state.landmarks {
309			if lm.x >= r.MinX && lm.x <= r.MaxX && lm.y >= r.MinY && lm.y <= r.MaxY {
310				out = append(out, Landmark{ID: id, X: lm.x, Y: lm.y, Count: lm.count})
311			}
312		}
313		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
314		if out == nil {
315			out = []Landmark{}
316		}
317		return out, nil
318	}
319	
320	// AsRejectError 返回错误对应的 *RejectError；不是段拒绝错误时返回 nil、false。
321	func AsRejectError(err error) (*RejectError, bool) {
322		var r *RejectError
323		if errors.As(err, &r) {
324			return r, true
325		}
326		return nil, false
327	}
