1	package posemap
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"math"
10		"os"
11		"path/filepath"
12	)
13	
14	// 文件布局（均为大端）：
15	//
16	//	magic     8 字节  "POSEMAP1"
17	//	version   uint16
18	//	length    uint32  payload 字节数
19	//	payload   length 字节（JSON，见 fileData）
20	//	crc       uint32  对 crc 之前全部字节的 CRC-32/IEEE
21	//
22	// 保存采用“同目录临时文件写完并 fsync 后 rename”的方式，成功导入对
23	// 调用方可见时文件必为完整的新版本；无法识别或校验失败的文件绝不被
24	// 覆盖（Create 用 O_EXCL，Open 只读取证）。
25	const (
26		fileMagic   = "POSEMAP1"
27		fileVersion = uint16(1)
28		headerLen   = 8 + 2 + 4
29	)
30	
31	type fileData struct {
32		Version    int            `json:"version"`
33		Config     Config         `json:"config"`
34		Trajectory []Pose         `json:"trajectory"`
35		Landmarks  []landmarkJSON `json:"landmarks"`
36		Segments   []segmentJSON  `json:"segments"`
37	}
38	
39	type landmarkJSON struct {
40		ID    string  `json:"id"`
41		X     float64 `json:"x"`
42		Y     float64 `json:"y"`
43		Count int     `json:"count"`
44	}
45	
46	type segmentJSON struct {
47		ID     string       `json:"id"`
48		Hash   string       `json:"hash"`
49		Result ImportResult `json:"result"`
50	}
51	
52	// encodeFile 把内存状态编码为完整文件字节。
53	func encodeFile(st *mapState) ([]byte, error) {
54		fd := fileData{
55			Version:    int(fileVersion),
56			Config:     st.config,
57			Trajectory: st.trajectory,
58			Landmarks:  make([]landmarkJSON, 0, len(st.landmarks)),
59			Segments:   make([]segmentJSON, 0, len(st.segments)),
60		}
61		for id, lm := range st.landmarks {
62			fd.Landmarks = append(fd.Landmarks, landmarkJSON{ID: id, X: lm.x, Y: lm.y, Count: lm.count})
63		}
64		for id, rec := range st.segments {
65			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
66		}
67		payload, err := json.Marshal(&fd)
68		if err != nil {
69			return nil, fmt.Errorf("posemap: encode state: %w", err)
70		}
71	
72		out := make([]byte, headerLen+len(payload)+4)
73		copy(out[0:8], fileMagic)
74		binary.BigEndian.PutUint16(out[8:10], fileVersion)
75		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
76		copy(out[headerLen:], payload)
77		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
78		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
79		return out, nil
80	}
81	
82	// loadFile 只读取证地解析地图文件。
83	func loadFile(path string) (*mapState, error) {
84		raw, err := os.ReadFile(path)
85		if err != nil {
86			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
87		}
88		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
89			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
90		}
91		version := binary.BigEndian.Uint16(raw[8:10])
92		if version != fileVersion {
93			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
94		}
95		length := binary.BigEndian.Uint32(raw[10:14])
96		if int(length) != len(raw)-headerLen-4 {
97			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
98		}
99		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
100		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
101			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
102		}
103	
104		var fd fileData
105		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
106			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
107		}
108		if err := validateLoaded(&fd); err != nil {
109			return nil, err
110		}
111	
112		st := &mapState{
113			config:     fd.Config,
114			trajectory: fd.Trajectory,
115			landmarks:  make(map[string]*landmarkState, len(fd.Landmarks)),
116			segments:   make(map[string]*segmentRecord, len(fd.Segments)),
117		}
118		for _, lm := range fd.Landmarks {
119			st.landmarks[lm.ID] = &landmarkState{x: lm.X, y: lm.Y, count: lm.Count}
120		}
121		for _, sg := range fd.Segments {
122			ids := sg.Result.LandmarkIDs
123			if ids == nil {
124				ids = []string{}
125			}
126			st.segments[sg.ID] = &segmentRecord{
127				hash:   sg.Hash,
128				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
129			}
130		}
131		return st, nil
132	}
133	
134	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
135	func validateLoaded(fd *fileData) error {
136		switch {
137		case fd.Version != int(fileVersion):
138			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
139		case len(fd.Trajectory) == 0:
140			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
141		}
142		if err := validateConfig(fd.Config); err != nil {
143			// 配置不合法不可能由本版本写出。
144			return fmt.Errorf("%w: %v", ErrCorrupt, err)
145		}
146		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
147		for _, lm := range fd.Landmarks {
148			if lm.ID == "" || lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
149				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
150			}
151			if _, dup := seenIDs[lm.ID]; dup {
152				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
153			}
154			seenIDs[lm.ID] = struct{}{}
155		}
156		segIDs := make(map[string]struct{}, len(fd.Segments))
157		for _, sg := range fd.Segments {
158			if sg.ID == "" || sg.Hash == "" {
159				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
160			}
161			if _, dup := segIDs[sg.ID]; dup {
162				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
163			}
164			segIDs[sg.ID] = struct{}{}
165		}
166		return nil
167	}
168	
169	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
170	func (m *Map) saveExclusive() error {
171		data, err := encodeFile(m.state)
172		if err != nil {
173			return err
174		}
175		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
176		if err != nil {
177			return err
178		}
179		return writeAndClose(f, data, m.path)
180	}
181	
182	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
183	func (m *Map) saveReplace() (err error) {
184		data, err := encodeFile(m.state)
185		if err != nil {
186			return err
187		}
188		dir, base := filepath.Split(m.path)
189		if dir == "" {
190			dir = "."
191		}
192		f, err := os.CreateTemp(dir, base+".tmp-*")
193		if err != nil {
194			return err
195		}
196		tmpName := f.Name()
197		// 任何失败路径都尽力清理临时文件。
198		defer func() {
199			if err != nil {
200				_ = os.Remove(tmpName)
201			}
202		}()
203		if err = writeAndClose(f, data, tmpName); err != nil {
204			return err
205		}
206		if err = os.Rename(tmpName, m.path); err != nil {
207			return err
208		}
209		return nil
210	}
211	
212	func writeAndClose(f *os.File, data []byte, name string) (err error) {
213		defer func() {
214			if cerr := f.Close(); err == nil {
215				err = cerr
216			}
217		}()
218		if _, err = f.Write(data); err != nil {
219			return err
220		}
221		if err = f.Sync(); err != nil {
222			return err
223		}
224		return nil
225	}
226	
227	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
228	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
229	func canonicalHash(frames []Frame) string {
230		h := sha256.New()
231		var lenBuf [4]byte
232		var numBuf [8]byte
233		putU32 := func(v uint32) {
234			binary.BigEndian.PutUint32(lenBuf[:], v)
235			h.Write(lenBuf[:])
236		}
237		putU64 := func(v uint64) {
238			binary.BigEndian.PutUint64(numBuf[:], v)
239			h.Write(numBuf[:])
240		}
241		putStr := func(s string) {
242			putU32(uint32(len(s)))
243			h.Write([]byte(s))
244		}
245	
246		putU32(uint32(len(frames)))
247		for _, fr := range frames {
248			putU64(uint64(fr.Time))
249			putU64(math.Float64bits(fr.DX))
250			putU64(math.Float64bits(fr.DY))
251			putU64(math.Float64bits(fr.DHeading))
252			putU64(math.Float64bits(fr.MoveVariance))
253			putU32(uint32(len(fr.Observations)))
254			for _, ob := range fr.Observations {
255				putStr(ob.ID)
256				putU64(math.Float64bits(ob.X))
257				putU64(math.Float64bits(ob.Y))
258			}
259		}
260		return fmt.Sprintf("%x", h.Sum(nil))
261	}
262

